  1020→
  1021→    // Check if search looks like a full Matrix user ID (@userId:domain)
  1022→    const isFullUserId = search.startsWith("@") && search.includes(":");
  1023→
  1024→    if (!isFullUserId) return this.instance.searchUsers(search, BigInt(20));
  1025→
  1026→    try {
